{
  "name": "DPS 可编程直流电源模块",
  "name_en": "DPS Programmable DC Power Supply Module",
  "manufacturer": "",
  "description": "DPS 系列可编程直流电源模块是一种可调输出电压与电流限制的直流稳压电源，常用于为电子电路提供稳定供电、器件测试、原型调试和教学实验。",
  "description_en": "A DPS series programmable DC power supply module is a regulated DC power source with adjustable output voltage and current limit, commonly used to power electronic circuits, test components, debug prototypes, and support teaching labs.",
  "tag_hints": [
    "programmable DC power supply",
    "constant-voltage constant-current",
    "bench electronics testing",
    "adjustable power source",
    "DC power module"
  ],
  "actions": [
    {
      "action_name": "auto-getVoltage",
      "description": "读取输出电压。",
      "description_en": "Read the output voltage."
    },
    {
      "action_name": "auto-getCurrent",
      "description": "读取输出电流。",
      "description_en": "Read the output current."
    },
    {
      "action_name": "auto-getPower",
      "description": "读取输出功率。",
      "description_en": "Read the output power."
    },
    {
      "action_name": "auto-setVoltage",
      "description": "设置输出电压。",
      "description_en": "Set the output voltage."
    },
    {
      "action_name": "auto-setCurrent",
      "description": "设置限流电流。",
      "description_en": "Set the current limit."
    },
    {
      "action_name": "auto-setOutput",
      "description": "打开或关闭电源输出。",
      "description_en": "Enable or disable the power output."
    },
    {
      "action_name": "auto-getInputVoltage",
      "description": "读取输入电压。",
      "description_en": "Read the input voltage."
    },
    {
      "action_name": "auto-getFwVersion",
      "description": "读取固件版本。",
      "description_en": "Read the firmware version."
    },
    {
      "action_name": "auto-getModel",
      "description": "读取设备型号。",
      "description_en": "Read the device model."
    },
    {
      "action_name": "auto-setKeyLock",
      "description": "设置面板按键锁定状态。",
      "description_en": "Set the front-panel key lock state."
    },
    {
      "action_name": "auto-getFullData",
      "description": "读取完整状态数据。",
      "description_en": "Read the full status data."
    }
  ]
}

